             SSHDotNetDiagnostics.TraceLogging = true;
-            int initialMessageCount = mRemoteNG.App.Runtime.MessageCollector.Count;
+            int initialMessageCount = mRemoteNG.App.Runtime.MessageCollector.Messages.Count();
